"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
type Request={request:string;reason:string};
export function CashierBankDepositVoid({scope,deposit,voided,onSaved}:{scope:HandoffScope;deposit:string;voided:boolean;onSaved:()=>void}){
 const [pending,setPending]=useState<Request|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);const key='irp.deposit.void.v1:'+ [scope.tenant,scope.property,scope.actor,deposit].join(':');
 function read():Request|null{const raw=sessionStorage.getItem(key);if(raw===null)return null;const r=JSON.parse(raw);if(!r||typeof r.request!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(r.request)||typeof r.reason!=='string'||r.reason!==r.reason.trim()||r.reason.length<4||r.reason.length>500||/[\x00-\x1f\x7f]/.test(r.reason))throw Error('Invalid pending void. Preserve it for recovery.');return {request:r.request,reason:r.reason}}
 useEffect(()=>{alive.current=true;try{setPending(read())}catch(e){setError(e instanceof Error?e.message:'Unable to recover void.')}return()=>{alive.current=false}},[key]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen deposits.');}
 async function run(r:Request,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const prior=read();if(prior&&JSON.stringify(prior)!==JSON.stringify(r))throw Error('Recover the pending void first.');const encoded=JSON.stringify(r);sessionStorage.setItem(key,encoded);if(sessionStorage.getItem(key)!==encoded)throw Error('Unable to preserve void recovery.');read();setPending(r);
 const value=await hotelRpc(status?'cashier_bank_deposit_void_status':'void_cashier_bank_deposit',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:r.request}:{p_tenant:scope.tenant,p_property:scope.property,p_deposit:deposit,p_request:r.request,p_reason:r.reason,p_confirmed:true});await identify();if(!alive.current)return;
 const v=value as Record<string,unknown>;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==r.request)throw Error('Void receipt scope changed.');let receipt=v;
 if(status){if(typeof v.found!=='boolean')throw Error('Invalid void recovery.');if(!v.found){if(v.result!==null)throw Error('Invalid void recovery.');if(!voided){setMessage('No saved void found. Retry the original request.');return}sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending void.');setPending(null);setMessage('Another void is already recorded. Your unsaved request was cleared.');return}receipt=v.result as Record<string,unknown>}
 if(!receipt||receipt.schema_version!==1||receipt.tenant_id!==scope.tenant||receipt.property_id!==scope.property||receipt.actor_id!==scope.actor||receipt.request_id!==r.request||receipt.deposit_id!==deposit||receipt.reason!==r.reason||receipt.voided!==true||receipt.cash_recovered!==false||receipt.journal_posted!==false||typeof receipt.replayed!=='boolean'||typeof receipt.created_at!=='string')throw Error('Void receipt does not match the request.');
 sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending void.');setPending(null);setMessage('Deposit declaration voided. The original record is retained.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Void interrupted. Check the saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section>{pending?<><p>Pending void: {pending.reason}</p><button disabled={busy} onClick={()=>void run(pending)}>Retry deposit void</button><button disabled={busy} onClick={()=>void run(pending,true)}>Check deposit void</button></>:!voided&&<details><summary>Void incorrect declaration</summary><form onSubmit={e=>{e.preventDefault();const reason=String(new FormData(e.currentTarget).get('reason')).trim();if(reason.length<4||reason.length>500||/[\x00-\x1f\x7f]/.test(reason)){setError('Enter a valid explanation.');return}void run({request:crypto.randomUUID(),reason})}}><fieldset disabled={busy}><label>Void explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm this declaration is incorrect. This does not recover money from a bank.</label><button>Void deposit declaration</button></fieldset></form></details>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}
